<?php
namespace App\Http\Requests\Tenant;use App\Domain\AI\Knowledge\Data\KnowledgeSearchQuery;use App\Domain\Network\Tenancy\TenantAccessService;use Illuminate\Foundation\Http\FormRequest;use Illuminate\Validation\Validator;
final class SearchKnowledgeRequest extends FormRequest{public function authorize():bool{return app(TenantAccessService::class)->canManageTenant($this->user());}protected function prepareForValidation():void{$this->merge(['question'=>is_string($this->input('question'))?trim($this->input('question')):$this->input('question')]);}public function rules():array{return['question'=>['required','string','max:2000'],'top_k'=>['nullable','integer','min:1','max:10']];}public function withValidator(Validator$v):void{$v->after(function($v){foreach(array_keys($this->all())as$key)if(!in_array($key,['_token','question','top_k'],true))$v->errors()->add($key,'Este campo no está permitido.');if($v->errors()->isEmpty())try{$this->queryData();}catch(\InvalidArgumentException){$v->errors()->add('question','La pregunta no cumple el formato permitido.');}});}public function queryData():KnowledgeSearchQuery{return KnowledgeSearchQuery::from($this->validated('question'),$this->validated('top_k',5));}}
